const crypto = require('crypto');

function capitalize(str = '') {
  return str.charAt(0).toUpperCase() + str.slice(1).toLowerCase();
}

function calculateAge(birthDateStr) {
  const [day, month, year] = birthDateStr.split('.').map(Number);
  const birthDate = new Date(year, month - 1, day);
  const now = new Date();

  let age = now.getFullYear() - birthDate.getFullYear();
  const m = now.getMonth() - birthDate.getMonth();

  if (m < 0 || (m === 0 && now.getDate() < birthDate.getDate())) {
    age--;
  }

  return age;
}

function convertUserInfo(user) {
  const [firstNameRaw, lastNameRaw] = user.name.split(' ');
  
  return {
    id: crypto.randomBytes(5).toString('hex'),
    firstName: capitalize(firstNameRaw),
    lastName: capitalize(lastNameRaw),
    dateBirth: user.dateBirth,
    age: String(calculateAge(user.dateBirth)),
    purpose: capitalize(user.purpose)
  };
};

module.exports = convertUserInfo;